/**
 * @summary Generate or refresh a city page
 */
export const generateCityBodyCitySlugRegExp = new RegExp('^[a-z0-9]+(?:-[a-z0-9]+)*$');
export const generateCityBodyCountrySlugRegExp = new RegExp('^[a-z0-9]+(?:-[a-z0-9]+)*$');
export const generateCityBodyForceDefault = false;

export const GenerateCityBody = zod.object({
  "citySlug": zod.string().regex(generateCityBodyCitySlugRegExp),
  "countrySlug": zod.string().regex(generateCityBodyCountrySlugRegExp),
  "force": zod.boolean().default(generateCityBodyForceDefault)
})

export const generateCityResponseDroppedCountMin = 0;



export const GenerateCityResponse = zod.object({
  "cityId": zod.string(),
  "cached": zod.boolean(),
  "droppedCount": zod.number().int().min(generateCityResponseDroppedCountMin)
})


